921	+/* ===== Đồng hồ theo múi giờ chỉ định (D-042) =====
922	+   Chỉ dùng Intl, không đụng DOM: chạy được dưới Node. Giờ tính theo `tz` (Đà Nẵng), không theo múi giờ máy khách. */
923	+
924	+export type EnvPhase = 'dawn' | 'day' | 'dusk' | 'night';
925	+
926	+const fmtCache = new Map<string, Intl.DateTimeFormat>();   // một bộ định dạng cho mỗi múi giờ (tạo Intl khá tốn)
927	+
928	+function envFmt(tz: string): Intl.DateTimeFormat {
929	+  let f = fmtCache.get(tz);
930	+  if (!f) {
931	+    f = new Intl.DateTimeFormat('en-GB', { timeZone: tz, hour: '2-digit', minute: '2-digit', second: '2-digit', hourCycle: 'h23' });
932	+    fmtCache.set(tz, f);
933	+  }
934	+  return f;
935	+}
936	+
937	+/** Giờ / phút / giây tại múi giờ `tz`; min = h*60+m. Chữ số Latin, 0–23 (nửa đêm là 0, không phải 24). */
938	+export function envClockParts(d: Date, tz: string): { h: number; m: number; s: number; min: number } {
939	+  let h = 0, m = 0, s = 0;
940	+  for (const p of envFmt(tz).formatToParts(d)) {
941	+    if (p.type === 'hour') h = parseInt(p.value, 10) % 24;
942	+    else if (p.type === 'minute') m = parseInt(p.value, 10);
943	+    else if (p.type === 'second') s = parseInt(p.value, 10);
944	+  }
945	+  return { h, m, s, min: h * 60 + m };
946	+}
947	+
948	+/** 348 → "05:48" */
949	+export function envHHMM(min: number): string {
950	+  const p = (n: number) => (n < 10 ? '0' : '') + n;
951	+  return p(Math.floor(min / 60) % 24) + ':' + p(Math.floor(min % 60));
952	+}
953	+
954	+/** Pha trong ngày theo phút; bình minh / hoàng hôn xét trước, rồi ngày, còn lại là đêm. */
955	+export function envPhase(min: number, sunrise: number, sunset: number, dawn: readonly [number, number], dusk: readonly [number, number]): EnvPhase {
956	+  if (min >= sunrise + dawn[0] && min < sunrise + dawn[1]) return 'dawn';
957	+  if (min >= sunset + dusk[0] && min < sunset + dusk[1]) return 'dusk';
958	+  if (min >= sunrise && min < sunset) return 'day';
959	+  return 'night';
960	+}
