1597	+  btnX.addEventListener('click', () => { openSheet('none'); blurInExplore(); });
1598	+  scrim.addEventListener('pointerdown', (e) => { e.preventDefault(); openSheet('none'); });
1599	+
1600	+  /* ----- Ô tô / xe máy trên cảm ứng: chỉ báo đứng dưới chú thích bản đồ nhỏ (#drMapNote). Chiều cao bản đồ (--dr-map-h) chỉ đặt trên #drHud, chú thích
1601	+     xuống dòng theo ngôn ngữ, nên đo đáy chú thích khi nó đổi cỡ (hiện ra, đổi ngôn ngữ, xoay máy) hoặc bản đồ đổi cỡ, ghi --env-dr-top cho CSS ----- */
1602	+  const note = document.getElementById('drMapNote'), drHud = document.getElementById('drHud');
1603	+  if (note && drHud && typeof ResizeObserver !== 'undefined') {
1604	+    const syncDr = () => {
1605	+      const b = note.getBoundingClientRect();
1606	+      if (b.height > 0) setStyle(root, '--env-dr-top', Math.round(b.bottom + cfg.driveGap) + 'px');
1607	+    };
1608	+    new ResizeObserver(syncDr).observe(note);
1609	+    new MutationObserver(syncDr).observe(drHud, { attributes: true, attributeFilter: ['style'] });
1610	+  }
1611	+
1612	+  /* ----- Tab ẩn: dừng đồng hồ và nhịp lấy số liệu; hiện lại: chạy tiếp (store tự lấy nếu đã quá hạn) ----- */
1613	+  document.addEventListener('visibilitychange', () => {
1614	+    const vis = !document.hidden;
1615	+    store.setVisible(vis);
1616	+    if (vis) { tick(true); schedule(); } else window.clearTimeout(clockTimer);
1617	+  });
1618	+  window.addEventListener('online', () => { void store.refresh(); });
1619	+
1620	+  if (document.hidden) store.setVisible(false);
1621	+  tick(true);
1622	+  store.start();
1623	+  if (!document.hidden) schedule();
1624	+
1625	+  return {
1626	+    store,
1627	+    render: () => tick(true),
1628	+    setNow(fn: (() => number) | null) { nowFn = fn || (() => Date.now()); tick(true); }
1629	+  };
1630	+}

