+/* ===== Giờ và thời tiết thực tế (D-042) =====
+   #env (ui/envUI.ts): chỉ báo #envPill luôn hiện + thẻ chi tiết #envCard (tờ 'env' của compactUI.ts, body.sheet-env). Kiểu chép từ prototype đã duyệt (phương án B).
+   Kính tối: nền trong, blur lớn, viền sáng mảnh, một quầng màu theo buổi thật (--acc theo data-phase). #env không định vị: chỉ báo (6), thẻ máy tính (9), lớp mờ (9), tờ đáy điện thoại (10) xếp lớp riêng.
+   Ẩn / hiện bằng display chỉ ở quy tắc theo ngữ cảnh (body.compact …), không ở quy tắc chung #env … (bẫy độ ưu tiên, xem #stJump). */
+#env{--acc:140,200,240;--tint:10,18,24;--glass:.56;font-family:var(--font-body);color:var(--text);}
+#env[data-phase="dawn"]{--acc:244,178,138;--tint:22,16,20;}
+#env[data-phase="day"]{--acc:140,200,240;--tint:9,19,27;}
+#env[data-phase="dusk"]{--acc:242,150,86;--tint:24,15,13;}
+#env[data-phase="night"]{--acc:138,164,236;--tint:7,11,26;--glass:.62;}
+#env .env-glass{
+  background:
+    radial-gradient(130% 90% at 100% 0%,rgba(var(--acc),.20),transparent 62%),
+    linear-gradient(165deg,rgba(var(--tint),calc(var(--glass) + .1)),rgba(var(--tint),var(--glass)));
+  border:1px solid rgba(255,255,255,.11);
+  backdrop-filter:blur(22px) saturate(150%);-webkit-backdrop-filter:blur(22px) saturate(150%);
+  box-shadow:0 18px 48px rgba(0,0,0,.34),0 2px 6px rgba(0,0,0,.2),inset 0 1px 0 rgba(255,255,255,.12);
+  transition:background .9s,border-color .25s,box-shadow .25s,transform .25s,opacity .2s;
+}
+html[dir=rtl] #env .env-glass{background:radial-gradient(130% 90% at 0% 0%,rgba(var(--acc),.20),transparent 62%),linear-gradient(195deg,rgba(var(--tint),calc(var(--glass) + .1)),rgba(var(--tint),var(--glass)));}   /* quầng sáng ở góc cuối dòng */
+#env .env-ico{width:1em;height:1em;flex:none;fill:none;stroke:currentColor;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round;color:rgb(var(--acc));transition:color .9s;}
+/* --- Chỉ báo: máy tính, tham quan: cạnh ⚙ (bản đủ: biểu tượng, nhiệt độ, vạch, HH:mm, giây, mô tả khi rê chuột, mũi tên) --- */
+#envPill{position:fixed;z-index:6;top:calc(17px + env(safe-area-inset-top,0px));inset-inline-start:calc(72px + env(safe-area-inset-left,0px));
+  align-items:center;gap:9px;height:44px;margin:0;padding:0;padding-inline:12px 14px;box-sizing:border-box;border-radius:12px;color:var(--text);cursor:pointer;font:inherit;-webkit-tap-highlight-color:transparent;}
+#env #envPill{display:inline-flex;}
+#envPill .env-ico{font-size:20px;}
+#envPill .t{font:600 23px/1 var(--font-display);color:var(--gold);font-variant-numeric:lining-nums tabular-nums;letter-spacing:.01em;}
+#envPill .sep{width:1px;height:16px;background:rgba(255,255,255,.16);}
+#envPill .clk{display:inline-flex;align-items:center;gap:4px;}   /* HH:mm + giây một khối dir="ltr": ar không đảo giây sang trước giờ */
+#envPill .hm{font:500 13.5px/1 var(--font-body);font-variant-numeric:tabular-nums;letter-spacing:.02em;}
+#envPill .ss{font:400 10.5px/1 var(--font-mono);color:var(--muted);opacity:.75;font-variant-numeric:tabular-nums;}
+#envPill .d{max-width:0;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;font-size:12px;color:var(--muted);opacity:0;transition:max-width .35s cubic-bezier(.2,.7,.2,1),opacity .25s,margin .35s;margin-inline-start:-9px;}
+#envPill .chev{width:10px;height:10px;stroke:var(--muted);fill:none;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round;transition:transform .3s;}
+@media (hover:hover){
+  #env #envPill:hover{border-color:rgba(255,255,255,.22);box-shadow:0 20px 50px rgba(0,0,0,.38),0 0 0 4px rgba(var(--acc),.08),inset 0 1px 0 rgba(255,255,255,.16);transform:translateY(-1px);}
+  body:not(.compact):not(.explore) #envPill:hover .d{max-width:180px;opacity:1;margin-inline-start:0;}
+}
+#env #envPill:active{transform:translateY(0) scale(.985);}
+#envPill:focus-visible,#envX:focus-visible{outline:2px solid var(--gold);outline-offset:2px;}
+body.sheet-env #env #envPill{border-color:rgba(var(--acc),.38);}
+body.sheet-env #envPill .chev{transform:rotate(180deg);}
+/* Bảng Cài đặt mở (máy tính, tham quan) phủ lên chỗ chỉ báo: chỉ báo nhường chỗ */
+body:not(.compact):not(.explore).sheet-settings #env #envPill{opacity:0;pointer-events:none;transform:translateY(-4px);visibility:hidden;transition:background .9s,border-color .25s,box-shadow .25s,transform .25s,opacity .2s,visibility 0s .2s;}   /* visibility: Tab không tới nút đã ẩn; trễ .2 s cho kịp mờ đi */
+/* --- Thẻ chi tiết: máy tính, rơi xuống dưới chỉ báo --- */
