+#env[data-state="offline"] .live{background:#f07b6b;}#env[data-state="offline"] .live::after{border-color:#f07b6b;}
+#env[data-state="loading"] .live{background:var(--muted);}#env[data-state="loading"] .live::after{border-color:var(--muted);}
+#env .env-clock{display:flex;align-items:baseline;justify-content:flex-start;gap:6px;margin-top:10px;}
+html[dir=rtl] #env .env-clock{justify-content:flex-end;}   /* cụm giờ dir="ltr": vẫn canh về đầu dòng của trang */
+#env .env-clock .hm{font:500 52px/.92 var(--font-display);letter-spacing:.005em;font-variant-numeric:lining-nums tabular-nums;}
+#env .env-clock .ss{font:400 13px/1 var(--font-mono);color:var(--muted);opacity:.7;font-variant-numeric:tabular-nums;}
+#env .env-date{margin-top:7px;font-size:12.5px;color:var(--text);opacity:.86;}
+#env .env-date::first-letter{text-transform:uppercase;}
+/* Vạch mặt trời: mọc → lặn, chấm là vị trí hiện tại (theo đồng hồ; daily=sunrise,sunset của Open-Meteo) */
+#env .env-sun{margin-top:14px;}
+#env .env-sun .track{position:relative;height:1px;background:linear-gradient(90deg,rgba(255,255,255,.08),rgba(var(--acc),.55),rgba(255,255,255,.08));}
